  - “非全1且异或为 $0$”：方案数为 $T$；  
  - “非全1且异或为 $1$”：方案数为 $T-1$（全 1不属于这一类）。

**状态转移：**

- 当 $n$ 为奇数时，由于“全 1”产生的 $(1,1)$与“非全1且异或为 $0$”产生的 $(0,0)$都使得 $X_b=Y_b$，故数组整体必须满足 $X=Y$。因此每个位有 $1+T$ 种选择，答案为 $(1+T)^m$。

- 当 $n$ 为偶数时，高位若选择“全 1”会使当前位出现 $(0,1)$，从紧状态转为松弛状态；在紧状态下只允许选择“非全1且异或为 $0$”。设从最高位开始连续有 $j$ 位处于紧状态后，第 $j+1$ 位选择“全 1”转为松弛状态（$0\le j\le m-1$），那么前 $j$ 位每位有 $(T-1)$ 种选择；转折位有 $1$ 种；之后每一位在松弛状态下可以任意选择三个合法方案，总数为 $2T$（即 $1+(T-1)+T=2T$）。此外还有一种情况是所有位都保持紧状态，即每位都选“非全1且异或为 $0$”，方案数为 $(T-1)^m$。因此答案为  
$\text{ans}$=$(T-1)^m$+$\sum_{j=0}^{m-1}(T-1)^j$,$(2T)^{m-1-j}.$
将求和化简可得最终公式  
$\text{ans}=\frac{(T-1)^m\cdot T+(2T)^m}{T+1}.$

其中 $T=2^{n-1}\mod (10^9+7)$。



## C++

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007;

// 快速幂求模
ll modPow(ll base, ll exp, ll mod) {
    ll res = 1;
    base %= mod;
    while(exp) {
        if(exp & 1) res = res * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return res;
}

// 求模逆元，mod 为质数
ll modInv(ll a, ll mod) {
    return modPow(a, mod - 2, mod);
}

class Solution {
public:
    void solve() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        int n, k;
        cin >> n >> k;
        // T = 2^(n-1) mod MOD
        ll T = modPow(2, n - 1, MOD);
        ll ans = 0;
        if(n % 2 == 1) {
            // n 为奇数时答案为 (T + 1)^k mod MOD
            ans = modPow(T + 1, k, MOD);
        } else {
            // n 为偶数时答案为 ((T-1)^k * T + (2T)^k) / (T+1) mod MOD
            ll term1 = modPow((T + MOD - 1) % MOD, k, MOD); // (T-1)^k
            term1 = term1 * T % MOD;
            ll term2 = modPow(2 * T % MOD, k, MOD); // (2T)^k
            ll numerator = (term1 + term2) % MOD;
            ll invDenom = modInv((T + 1) % MOD, MOD);
            ans = numerator * invDenom % MOD;
        }
        cout << ans << "\n";
    }
};

int main(){
    Solution sol;
    sol.solve();
    return 0;
}
