# 快速幂求模
def mod_pow(base: int, exp: int, mod: int) -> int:
    res = 1
    base %= mod
    while exp:
        if exp & 1:
            res = res * base % mod
        base = base * base % mod
        exp //=  2
    return res

# 求模逆元，mod 为质数时使用快速幂
def mod_inv(a: int, mod: int) -> int:
    return mod_pow(a, mod - 2, mod)

class Solution:
    def solve(self):
        import sys
        input_data = sys.stdin.read().split()
        n = int(input_data[0])
        k = int(input_data[1])
        # T = 2^(n-1) mod MOD
        T = mod_pow(2, n - 1, MOD)
        if n % 2 == 1:
            # 当 n 为奇数时，答案为 (T + 1)^k mod MOD
            ans = mod_pow(T + 1, k, MOD)
        else:
